stock=stock_at_target
future_lost=0
first_stockout=-1
for e in sorted(data['future_schedule'], key=lambda r:(r['event_time'],r['event_id'])):
    if e['kind']=='receipt':
        stock += e['quantity']
    else:
        unmet=max(0, e['quantity']-stock)
        if unmet>0 and first_stockout==-1:
            first_stockout=e['event_time']
        future_lost += unmet
        stock -= min(stock,e['quantity'])
stock, future_lost, first_stockout
